console.log('     projection ' + (after2.proj || '').length + ' chars, scenes=' + after2.sceneCount
  + ', stages=' + JSON.stringify(seamCalls.map(c => c.stage)));
console.log('     console during the seam:');
rec1.console.filter(c => c.phase === 'scene2').slice(-8)
  .forEach(c => console.log('       · ' + c.txt.slice(0, 150)));
fs.writeFileSync(OUT + '/console.json', JSON.stringify(rec1.console, null, 2));
